    {
      "key": "headline",
      "text": "Adopt {arm:atlas-m}. It is the only option that meets all quality gates while staying within the latency budget."
    },
    {
      "key": "lede",
      "text": "{arm:atlas-m} passes all quality and latency criteria across every task. Relaxing the latency budget would allow consideration of {arm:atlas-l}."
    },
    {
      "key": "decision.recommendation",
      "text": "Deploy {arm:atlas-m}. It meets the quality threshold on all tasks and maintains p95 latency under {criteria.p95.threshold} seconds across the board."
    },
    {
      "key": "decision.why_not",
      "text": "{arm:atlas-l} breaches the latency budget on three tasks; {arm:brisk-s} and {arm:open-70b} fail multiple domain and safety quality gates."
    },
    {
      "key": "decision.watch",
      "text": "{weakest.arm} sits directly on the threshold for {weakest.criterion} at {weakest.value|pct} against {weakest.threshold|pct} with a margin of {weakest.margin|pts}. Monitor resolution quality in troubleshooting."
    },
    {
      "key": "decision.next",
      "text": "Test speculative decoding or prompt pruning on {arm:atlas-l} to evaluate whether its p95 latency can reach the {criteria.p95.threshold} second target."
    },
    {
      "key": "summary.0.title",
      "text": "Task Gate Compliance by Candidate"
    },
    {
      "key": "sections.gate_performance.eyebrow",
      "text": "Gate evaluation"
    },
    {
      "key": "sections.gate_performance.headline",
      "text": "{arm:atlas-m} clears every task gate while competing candidates miss on latency or accuracy."
    },
    {
      "key": "sections.gate_performance.takeaway",
      "text": "Columns represent tasks; cells show gate compliance against quality and latency thresholds."
    },
    {
      "key": "sections.gate_performance.title",
      "text": "Gate outcomes across evaluated tasks"
    },
    {
      "key": "sections.gate_performance.caption",
      "text": ""
    },
    {
      "key": "durable_claims.0",
      "text": "{arm:atlas-m} achieved a mean of {task.trouble.atlas-m.resolves.mean|pct} on troubleshooting issue resolution, meeting the gate threshold of {criteria.trouble.resolves.threshold|pct}."
    },
    {
      "key": "method.0.term",
      "text": "Quality Gates"
    },
    {
      "key": "method.0.text",
      "text": "Requires meeting calibrated judge criteria per task alongside task-level p95 latency thresholds."
    },
    {
      "key": "method.1.term",
      "text": "Latency Measurement"
    },
    {
      "key": "method.1.text",
      "text": "Measured end to end from user message submission to final generated token in staging."
    },
    {
      "key": "method.2.term",
      "text": "Judge Calibration"
    },
    {
      "key": "method.2.text",
      "text": "Overall quality graded via a calibrated judge exhibiting {judged.overall.agreement|pct} agreement across {judged.overall.calibration_ratings} samples."
    },
    {
      "key": "method.3.term",
      "text": "Cost Basis"
    },
    {
      "key": "method.3.text",
      "text": "Derived from measured token consumption multiplied by vendor list prices per 1,000 conversations."
    },
    {
      "key": "explore.title",
      "text": "Explore Gate Thresholds"
    },
    {
      "key": "explore.recomputes",
      "text": "Adjusting the p95 latency budget changes gate outcomes; raising the limit above 4.9 seconds enables {arm:atlas-l}."
    },
    {
      "key": "explore.controls.latency_p95_limit.title",
      "text": "p95 Latency Budget (s)"
    }
  ]
}

